head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf41000";
scwin.browseBtn = null;
scwin.fileInfoSection = null;
scwin.fileCounter = 0;
scwin.upd_fileInput = null;
scwin.dmenus = undefined;
scwin.dropZone = undefined;
scwin.browseBtn = undefined;
scwin.addedFiles = undefined;
scwin.removeFile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_datefmt_cal_efReqStartDt
 * @description TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — ISREAL
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_efReqStartDt = function () { $c.date.checkCalendarFormat("cal_efReqStartDt", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_efReqEndDt
 * @description 초기화 — datefmt cal ef Req End Dt
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_efReqEndDt = function () { $c.date.checkCalendarFormat("cal_efReqEndDt", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $("#fileUpload").change(function() {
                const files = this.files;
                if (files && files.length > 0) {
                    for (let i = 0; i < files.length; i++) {
                        const file = files[i];
                        scwin.appendFile(file);
                    }
                }
                $(this).val('');
                scwin.fileInfoSection.setStyle("display", "");
        });
        $("#upd_fileInput").change(async function() {
                const files = this.files;
                if (files && files.length > 0) {
                    for (let i = 0; i < files.length; i++) {
                        if (!scwin.addedFiles.has(files[i].name)) {
                            scwin.addedFiles.add(files[i].name);
                            scwin.appendFile(files[i]);
                        } else {
                            await $c.win.alert("[" + files[i].name + "] 파일이 이미 추가되었습니다.");
                        }
                    }
                }
                $(this).val('');
                scwin.fileInfoSection.setStyle("display", "");
        });
        $("#saveBtn").click(async function() {
                if ($("#fileInfoTable tbody tr").length === 0) {
                    await $c.win.alert("파일을 선택해주세요.");
                    return false;
                }
                const current_time = dma_hiddenStore.get("areaNowTimer");
                if (current_time < "160000" && ((String(((dma_pageContext.get("ISREAL") ?? "")) == null ? '' : ((dma_pageContext.get("ISREAL") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ISREAL") ?? "")) == null ? '' : ((dma_pageContext.get("ISREAL") ?? "")))) === "real1" || (String(((dma_pageContext.get("ISREAL") ?? "")) == null ? '' : ((dma_pageContext.get("ISREAL") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ISREAL") ?? "")) == null ? '' : ((dma_pageContext.get("ISREAL") ?? "")))) === "real2")) {
                    await $c.win.alert("16시 이후 업로드가 가능합니다.");
                    return;
                }
                if (await $c.win.confirm("업로드 하시겠습니까?")) {
                    scwin.reNames();
                    (document.SendForm || { elements: [] }).action = "/upload/uploadFile.do";
                    $c.util.getComponent('dma_searchListReq').set('method', "uploadKsdExcelFile");
                    const p = {}; p["method"] = $c.util.getComponent("dma_searchListReq").get("method"); p["isurCd"] = $c.util.getComponent("dma_searchListReq").get("isurCd"); p["fileInput"] = $c.util.getComponent("upd_fileInput").getValue(); p["efReqStartDt"] = $c.util.getComponent("cal_efReqStartDt").getValue(); p["efReqEndDt"] = $c.util.getComponent("cal_efReqEndDt").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/jldbnf41000/jldbnf41000.xml', p);
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf41000.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldbnf41000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":9
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

try { scwin.dropZone =document.querySelector('.file-drop-zone'); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

try { scwin.browseBtn =$c.util.getComponent('browseBtn'); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

try { scwin.addedFiles =new Set(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf41000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.browseBtn = $c.util.getComponent('browseBtn');
        scwin.fileInfoSection = $c.util.getComponent('fileInfoSection');
        scwin.upd_fileInput = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_fileInput') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_fileInput"]');
        scwin.removeFile = removeFile;
        scwin.init_datefmt_cal_efReqStartDt();
        scwin.init_datefmt_cal_efReqEndDt();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf41000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name div_21_onclick
 * @description div_21 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.div_21_onclick = function(e){
    try {
        $('#fileUpload').click()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf41000.div_21_onclick' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description btn_searchList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf41000.btn_searchList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: action ?? "/upload/uploadFile.do",
        ref: "dma_searchListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appendFile
 * @description append File 처리
 * @param {*} file file
 * @returns {void}
 * @hidden N
 */
scwin.appendFile = function (file) {
    scwin.fileCounter++;
    const fileName = file.name;
    const fileSize = scwin.formatFileSize(file.size);
    const fileDate = new Date().toLocaleString();
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.name = "attachFiles";
    fileInput.id = "uploadFile" + scwin.fileCounter;
    fileInput.setStyle("display", "none");
    const dataTransfer = new DataTransfer();
    dataTransfer.items.add(file);
    fileInput.files = dataTransfer.files;
    $c.util.getComponent("fileInfoTable").appendChild(fileInput);
    const newRow = "<tr id='file" + scwin.fileCounter + "'>" + "<td>" + fileName + "<input type='hidden' name='attach_file_tp_cd' value='29'></td>" + "<td>" + fileSize + "<input type='hidden' name='file_coment' value='예탁원파일'></td>" + "<td class='txc'><span id='' class='button small delete' onclick='removeFile(" + scwin.fileCounter + "); return false;'>삭제</span></td>" + "</tr>";
    $("#fileInfoTable tbody").append(newRow);
};

/**
 * @method
 * @name formatFileSize
 * @description format File Size 처리
 * @param {*} bytes bytes
 * @returns {void}
 * @hidden N
 */
scwin.formatFileSize = function (bytes) {
    if (bytes === 0) {
        return '0 Bytes';
    }
    const k = 1024, sizes = ['Bytes', 'KB', 'MB', 'GB'], i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

function removeFile(id) {
    const fileInput = $c.util.getComponent("uploadFile" + id);
    if (fileInput) {
        fileInput.parentNode.removeChild(fileInput);
    }
    $("#file" + id).remove();
    if ($("#fileInfoTable tbody tr").length === 0) {

    }
    scwin.addedFiles.delete(fileInput.files[0].name);
}

/**
 * @method
 * @name reNames
 * @description re Names 처리
 * @returns {void}
 * @hidden N
 */
scwin.reNames = function () {
    let nIdx = 0;
    $.each($("input:file"), function(i) {
            const _name = $(this).attr("name");
            if (_name === "fileInput") {
                $(this).value = "";
            } else {
                $(this).attr("name", "attachFiles[" + nIdx + "]");
                nIdx++;
            }
    });
};

/**
 * @method
 * @name consoleLog
 * @description console Log 처리
 * @returns {void}
 * @hidden N
 */
scwin.consoleLog = function () {
    void("---------------------------------");
    scwin.addedFiles.forEach(function(item) {
            return void(item);
    });
    void("---------------------------------");
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    $c.util.getComponent('dma_searchListReq').set('method', 'uploadForm');
    await scwin.tx_fn_searchList('/upload/uploadFile.do');
};
